import os
import boto3

def filter_metric_dimensions(payload, config=None):
    config = config or {}
    cloudwatch = boto3.client(
        "cloudwatch",
        region_name=config.get("region") or os.environ.get("AWS_REGION") or os.environ.get("AWS_DEFAULT_REGION") or "us-east-1",
    )
    result = cloudwatch.get_metric_data(
        MetricDataQueries=[
            {
                "Id": "m1",
                "MetricStat": {
                    "Metric": {
                        "Namespace": payload["namespace"],
                        "MetricName": payload["metric_name"],
                        "Dimensions": [
                            {"Name": k, "Value": v}
                            for k, v in (payload.get("dimensions") or payload.get("resource_labels") or {}).items()
                        ],
                    },
                    "Period": int(payload.get("period", 300)),
                    "Stat": payload.get("stat", "Average"),
                },
                "ReturnData": True,
            }
        ],
        StartTime=payload["start_time"],
        EndTime=payload["end_time"],
        ScanBy=payload.get("scan_by", "TimestampDescending"),
        MaxDatapoints=int(payload.get("max_datapoints", 100)),
    )
    return result
